package com.bank.secondsmallest;

import java.util.*;
import java.util.logging.*;

public class SecondSmallestDemo {
    private static final Logger log = Logger.getLogger("SecondSmallest");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> fees = List.of(50, 50, 100, 25, 75);
        SecondSmallestService service = new SecondSmallestService();

        log.info(() -> "Second smallest distinct: "
            + service.secondSmallest(fees).orElse(-1));   // 50 (25 is smallest)
    }
}

// ─── Would be in service/SecondSmallestService.java ───
class SecondSmallestService {
    Optional<Integer> secondSmallest(List<Integer> nums) {
        return nums.stream()
            .distinct()          // distinct values
            .sorted()            // natural ascending order
            .skip(1)             // drop the smallest
            .findFirst();        // → second-smallest
    }
}
